232	    @Override
233	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
234	        HttpHeaders headers = new HttpHeaders();
235	        Visit visit = visitMapper.toVisit(visitFieldsDto);
236	        Pet pet = new Pet();
237	        pet.setId(petId);
238	        visit.setPet(pet);
239	        this.clinicService.saveVisit(visit);
240	        VisitDto visitDto = visitMapper.toVisitDto(visit);
241	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
242	            .buildAndExpand(visit.getId()).toUri());
243	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
244	    }
245	
246	
247	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
248	    @Override
249	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
250	        Owner owner = this.clinicService.findOwnerById(ownerId);
251	        if (owner != null) {
252	            Pet pet = owner.getPet(petId);
253	            if (pet != null) {
254	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
255	            }
256	        }
257	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
258	    }
259	}
